<?php
// Inspection / claims are an append-only journal. Actual return receiving owns stock movements.
function rf_url($platform,$order){return '?'.http_build_query(['page'=>'return_followup','platform'=>$platform,'order'=>$order]);}
function rf_require($write=false){if(!access_page_allowed('return_followup')||($write&&!can_action('return_confirm')))throw new Exception('Return follow-up access required.');}
function rf_target($input){$pl=stock_platform($input['platform']??'');$no=trim((string)($input['order']??''));if($no===''||mb_strlen($no)>100)throw new Exception('Enter a valid Order ID.');$o=om_find($pl,om_shops()[$pl],$no);if($o)$no=$o['order_no'];$refs=or_numbers($pl,$no);$marks=implode(',',array_fill(0,count($refs),'?'));$args=array_merge([$pl],$refs);$receipts=om_query('SELECT r.*,b.batch_ref,b.status batch_status,p.master_sku,p.name FROM posted_returns r JOIN return_batches b ON b.id=r.batch_id JOIN products p ON p.id=r.product_id WHERE r.platform=? AND r.original_ref IN ('.$marks.') AND r.reversed=0 AND b.status=\'Posted\' ORDER BY r.id',$args)->fetchAll();$wrong=ix_cases_ready()?om_query('SELECT * FROM return_investigations WHERE platform=? AND order_no IN ('.$marks.') ORDER BY id',$args)->fetchAll():[];$legacy=[];foreach(om_query("SELECT i.id,i.batch_id,i.product_id,p.master_sku,p.name,i.qty,i.source_platform FROM inflows i JOIN products p ON p.id=i.product_id WHERE i.reference_no IN (".$marks.") AND i.type='Customer Return - Good' AND (i.source_platform=? OR COALESCE(i.source_platform,'')='') AND i.reversed_by_request IS NULL",array_merge($refs,[$pl])) as $r){if(($r['source_platform']??'')===''){ $metadata=om_query('SELECT result_json FROM inflow_batches WHERE id=?',[$r['batch_id']])->fetchColumn();if((json_decode($metadata?:'{}',true)['return_platform']??null)!==$pl)continue;}$legacy[]=$r+['destination'=>'Sellable · '.$pl,'condition'=>'Good Item'];}foreach(om_query("SELECT n.id,n.product_id,p.master_sku,p.name,n.qty,n.condition_type FROM non_sellable n JOIN products p ON p.id=n.product_id WHERE n.platform=? AND n.order_id IN (".$marks.") AND n.origin='Customer Return' AND n.reversed_by_request IS NULL",$args) as $r)$legacy[]=$r+['destination'=>'Non-Sellable','condition'=>$r['condition_type']];if(!$o&&!$receipts&&!$wrong&&!$legacy)throw new Exception('Order or physically received return case not found.');return ['platform'=>$pl,'order'=>$no,'o'=>$o?:null,'receipts'=>$receipts,'wrong'=>$wrong,'legacy'=>$legacy,'key'=>hash('sha256',$pl.'|'.$no)];}
function rf_journal(){if(!isset($GLOBALS['RF_JOURNAL'])){$GLOBALS['RF_JOURNAL']=[];foreach(om_query("SELECT e.*,u.name actor FROM om_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.event_type='Return follow-up workflow' ORDER BY e.id") as $e){$d=json_decode($e['details_json'],true)?:[];if(isset($d['key']))$GLOBALS['RF_JOURNAL'][$d['key']]=['event_id'=>(int)$e['id'],'recorded_at'=>$e['created_at'],'actor'=>$e['actor']]+$d;}}return $GLOBALS['RF_JOURNAL'];}
function rf_state($t){$saved=rf_journal()[$t['key']]??[];$o=$t['o'];$received=array_sum(array_column($t['receipts'],'qty'))+array_sum(array_column($t['legacy'],'qty'));$none=$o&&in_array($o['aftersales_resolution']??'',['Refund Only','No Return Required','No Return'],true);$complete=$o&&$received>0&&oa_received_complete($o);$inspection=$saved['inspection']??'Awaiting Actual Return';if($received>0||$t['wrong'])$inspection='Inspected';$receiving=$none?'No Physical Return':($t['wrong']?'Wrong Item Received — For Investigation':($complete?'Fully Received':($received>0?($o?'Partially Received':'Received — Original Order Not Recorded'):(in_array($inspection,['For Inspection','Inspected'],true)?$inspection.' — Receipt Not Yet Posted':'Awaiting Actual Return'))));return ['event_id'=>$saved['event_id']??0,'inspection'=>$inspection,'claims'=>$saved['claims']??'Not Yet Assessed','remarks'=>$saved['remarks']??'','attachment'=>$saved['attachment']??null,'receiving'=>$receiving,'received_qty'=>$received,'saved'=>$saved];}
function rf_claims(){return ['Not Yet Assessed','For Filing of Claim','Claim Filed','Approved','Rejected','Closed'];}
function rf_save($input,$file=null){rf_require(true);return process_transaction(function()use($input,$file){$t=rf_target($input);if($t['o'])om_order($t['o']['id'],true);else {foreach(array_merge($t['receipts'],$t['legacy']) as $r)om_query('SELECT id FROM products WHERE id=? FOR UPDATE',[$r['product_id']])->fetch();}if(!$t['o']&&!$t['receipts']&&$t['wrong'])om_query('SELECT id FROM return_investigations WHERE id=? FOR UPDATE',[$t['wrong'][0]['id']])->fetch();unset($GLOBALS['RF_JOURNAL']);$t=rf_target($input);$s=rf_state($t);if((int)($input['revision']??-1)!==$s['event_id'])throw new Exception('Follow-up changed. Refresh before saving; no stock changed.');$reported=$t['o']?oa_reported($t['o'])['status']:null;if(!$t['receipts']&&!$t['wrong']&&!$t['legacy']&&!in_array($reported,['Return / Refund','Failed Delivery','Cancelled'],true))throw new Exception('This order has no return / refund follow-up or actual receipt.');$inspection=$input['inspection']??'';$claims=$input['claims']??'';if(!in_array($inspection,['Awaiting Actual Return','For Inspection','Inspected'],true)||!in_array($claims,rf_claims(),true))throw new Exception('Select valid inspection and claims statuses.');if($s['receiving']==='No Physical Return'&&$inspection!=='Awaiting Actual Return')throw new Exception('This order was resolved without a physical return. Review the order resolution first.');if($s['inspection']==='Inspected'&&$inspection!=='Inspected')throw new Exception('Existing posted receipts / wrong-item custody retain their inspected history.');if($inspection!=='Awaiting Actual Return'&&$s['inspection']==='Awaiting Actual Return'&&empty($input['physical_ack']))throw new Exception('Confirm the item is physically received before inspection. This does not post stock.');if($inspection==='Awaiting Actual Return'&&$s['inspection']==='For Inspection')throw new Exception('Do not remove an actual physical receipt acknowledgement. Record a correction in remarks.');if(in_array($claims,['Approved','Rejected'],true)&&!in_array($s['claims'],['Claim Filed','Approved','Rejected'],true))throw new Exception('Record Claim Filed before a claim outcome.');if($s['claims']==='Not Yet Assessed'&&$claims==='Closed')throw new Exception('Record the claim assessment before closing it.');$remarks=process_reason($input['remarks']??'');if(mb_strlen($remarks)>4000)throw new Exception('Remarks are limited to 4000 characters.');$attachment=$s['attachment'];if($file&&($file['error']??UPLOAD_ERR_NO_FILE)!==UPLOAD_ERR_NO_FILE){if(($file['error']??-1)!==UPLOAD_ERR_OK)throw new Exception('Attachment upload failed.');validate_upload_file($file,['pdf','png','jpg','jpeg']);$attachment=store_upload($file,'return_claims','RETURN');}$d=['key'=>$t['key'],'platform'=>$t['platform'],'order'=>$t['order'],'inspection'=>$inspection,'claims'=>$claims,'remarks'=>$remarks,'attachment'=>$attachment,'previous'=>['inspection'=>$s['inspection'],'claims'=>$s['claims']],'stock_effect'=>'No stock change; physical receiving and condition posting are separate.'];om_event($t['o']['id']??null,null,'Return follow-up workflow',$d);unset($GLOBALS['RF_JOURNAL']);audit('Update return inspection / claims','Return',$t['order'],$inspection.'; '.$claims.'; '.$remarks.'; no stock change.');return $t;});}
function rf_queue(){if(!om_ready())return [];$rows=[];$seen=[];foreach(om_query('SELECT * FROM om_orders ORDER BY fulfillment_date,id') as $o){$key=hash('sha256',$o['platform'].'|'.$o['order_no']);$saved=rf_journal()[$key]??[];$pending=oc_return_pending($o)||($o['posting']!=='Posted'&&oa_reported($o)['status']==='Return / Refund'&&$o['monitoring']!=='Resolved');$claim=in_array($saved['claims']??'',['For Filing of Claim','Claim Filed','Approved','Rejected'],true);if(!$pending&&!$claim&&($saved['inspection']??'')!=='For Inspection')continue;$t=rf_target(['platform'=>$o['platform'],'order'=>$o['order_no']]);if(!$pending&&!$claim&&rf_state($t)['inspection']!=='For Inspection')continue;$rows[]=['target'=>$t,'state'=>rf_state($t),'reported'=>oa_reported($o)['status']];$seen[$key]=true;}foreach(rf_journal() as $key=>$saved)if(!isset($seen[$key])&&in_array($saved['claims'],['For Filing of Claim','Claim Filed','Approved','Rejected'],true)){$t=rf_target($saved);$rows[]=['target'=>$t,'state'=>rf_state($t),'reported'=>'Actual return'];$seen[$key]=true;}if(ix_cases_ready())foreach(om_query('SELECT DISTINCT platform,order_no FROM return_investigations') as $c){$key=hash('sha256',$c['platform'].'|'.$c['order_no']);if(isset($seen[$key])||(rf_journal()[$key]['claims']??'')==='Closed')continue;$t=rf_target(['platform'=>$c['platform'],'order'=>$c['order_no']]);$rows[]=['target'=>$t,'state'=>rf_state($t),'reported'=>'Wrong Item Received'];$seen[$key]=true;}return $rows;}
function rf_notification_tasks(){if(!can_action('return_confirm')||!access_page_allowed('return_followup'))return [];$n=count(rf_queue());return $n?[['title'=>'ICO return / refund — receiving, inspection or claims follow-up','count'=>$n,'url'=>'index.php?page=return_followup']]:[];}
function rf_link($pl,$no){return '<a class="btn ghost sm" href="'.e(rf_url($pl,$no)).'">Inspection / Claims</a>';}
function rf_evidence_path($event){rf_require();$r=om_query("SELECT details_json FROM om_events WHERE id=? AND event_type='Return follow-up workflow'",[(int)$event])->fetch();$d=json_decode($r['details_json']??'',true)?:[];$root=realpath(__DIR__.'/uploads/return_claims');$path=realpath(__DIR__.'/'.($d['attachment']??''));if(!$root||!$path||!is_file($path)||!str_starts_with(strtolower(str_replace('\\','/',$path)),strtolower(str_replace('\\','/',$root)).'/'))throw new Exception('Attachment unavailable.');return $path;}
